import math
import pytest
from hypothesis import given
import hypothesis.strategies as st

from solution import f


def reference(n):
    out = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            out.append(math.factorial(i))
        else:
            out.append(i * (i + 1) // 2)
    return out


def test_example_five_equals_spec():
    assert f(5) == [1, 2, 6, 24, 15]


def test_example_decomposed_spec():
    # i=1 odd -> sum 1..1 = 1
    # i=2 even -> 2! = 2
    # i=3 odd -> 1+2+3 = 6
    # i=4 even -> 4! = 24
    # i=5 odd -> 1+..+5 = 15
    expected = [1, 2, 6, 24, 15]
    result = f(5)
    assert len(result) == 5
    for idx, exp in enumerate(expected, start=1):
        assert result[idx - 1] == exp


def test_zero_returns_empty():
    assert f(0) == []


def test_small_values_from_spec():
    assert f(1) == [1]
    assert f(2) == [1, 2]
    assert f(3) == [1, 2, 6]
    assert f(4) == [1, 2, 6, 24]
    assert f(6) == [1, 2, 6, 24, 15, 720]
    assert f(7) == [1, 2, 6, 24, 15, 720, 28]


@given(st.integers(min_value=0, max_value=30))
def test_size_matches_n(n):
    assert f(n) == reference(n)
    assert len(f(n)) == n


@given(st.integers(min_value=0, max_value=30))
def test_equivalence_to_reference_model(n):
    assert f(n) == reference(n)


@given(st.integers(min_value=1, max_value=30))
def test_even_positions_are_factorials(n):
    res = f(n)
    for i in range(1, n + 1):
        if i % 2 == 0:
            assert res[i - 1] == math.factorial(i)


@given(st.integers(min_value=1, max_value=30))
def test_odd_positions_are_triangular_numbers(n):
    res = f(n)
    for i in range(1, n + 1):
        if i % 2 == 1:
            assert res[i - 1] == i * (i + 1) // 2
            assert res[i - 1] == sum(range(1, i + 1))


@given(st.integers(min_value=1, max_value=30))
def test_elements_are_positive_ints(n):
    res = f(n)
    for v in res:
        assert isinstance(v, int)
        assert v > 0


@given(st.integers(min_value=0, max_value=30))
def test_prefix_consistency(n):
    # f(n)[:m] == f(m) for m <= n : list is prefix-closed
    full = f(n)
    for m in range(0, n + 1):
        assert full[:m] == f(m)


@given(st.integers(min_value=3, max_value=30))
def test_last_element_closed_form(n):
    res = f(n)
    if n % 2 == 0:
        assert res[-1] == math.factorial(n)
    else:
        assert res[-1] == n * (n + 1) // 2


@given(st.integers(min_value=-10, max_value=-1))
def test_negative_input_does_not_return_wrong_size(n):
    # Spec requires list of size n; for n < 0 no list can satisfy it,
    # so a spec-compliant implementation must raise or return empty.
    # It must NOT return a non-empty list of wrong length (e.g. [1, 2]).
    try:
        res = f(n)
    except (ValueError, TypeError, OverflowError):
        return
    assert isinstance(res, list)
    assert len(res) == 0, f"negative n={n} must not yield list of length {len(res)}"


@given(st.sampled_from([None, "5", 5.0, 5.5, [5], (5,)]))
def test_invalid_type_raises(bad):
    with pytest.raises(Exception):
        f(bad)
